head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.addWindow1_onclick = function(e) {
    scwin.addWindow("1");
};
scwin.addWindow2_onclick = function(e) {
    scwin.addWindow("2");
};
scwin.addWindow = function(windowIdx) {
    windowContainer1.createWindow("Window" + windowIdx, null, "windowContainer_spaAuto_WPFF-171_(WSQ-3497)_sub" + windowIdx + ".xml");
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'windowContainer1_subWindow0_iframe') != null;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    //windowContainer1_subWindow0_iframe이 존재하는지 확인
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //createdby SangWook
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
